-- multi_step_00: Return IDs of points strictly inside the polygon AND at most 2 projected meters from the reference point. Order by distance then ID.
WITH p(id,geom) AS (VALUES ('P0',ST_GeomFromText('POINT(5 5)',3857)),('P1',ST_GeomFromText('POINT(0 5)',3857)),('P2',ST_GeomFromText('POINT(-1 5)',3857)),('P3',ST_GeomFromText('POINT(0 0)',3857)),('P4',ST_GeomFromText('POINT(11 5)',3857))), ranked AS (SELECT id,ST_Distance(geom,ST_GeomFromText('POINT(5 5)',3857)) d FROM p WHERE ST_Contains(ST_GeomFromText('POLYGON((0 0,10 0,10 10,0 10,0 0))',3857),geom) AND ST_DWithin(geom,ST_GeomFromText('POINT(5 5)',3857),2)) SELECT COALESCE(jsonb_agg(id ORDER BY d,id),'[]'::jsonb) AS answer FROM ranked;

